const cfg = $('⚙️ Configuration').first().json;
const input = $input.first().json;
const rawIn = JSON.stringify(input, null, 2);

const systemMsg = `Tu es consultant automation (n8n + IA) pour agences SEA françaises.
Réponds UNIQUEMENT avec un JSON valide, sans markdown, sans texte avant ou après.`;

const userMsg = `Génère un mini-diagnostic business.

INPUT:
${rawIn}

STRUCTURE JSON EXACTE:
{
  "diagnostic_summary": "2-4 phrases",
  "quick_wins": [
    {"title":"...","impact_level":"high|medium|low","effort_level":"low|medium|high","expected_hours_saved_weekly":0,"implementation_note":"..."}
  ],
  "roi_estimate": {"hours_saved_weekly":0,"hours_saved_monthly":0,"estimated_value_monthly_eur":0,"payback_period_weeks":0},
  "plan_14_days": ["Jour 1-2: ...","Jour 3-5: ...","Jour 6-10: ...","Jour 11-14: ..."],
  "offer_recommendation": {"recommended_option":"A|B","reason":"...","option_a_price_eur":2000,"option_b_price_eur":3000},
  "cta_message": "phrase courte"
}

Règles: exactement 5 quick_wins; prix A=2000 B=3000; chiffrage réaliste.`;

const ollama_request = {
  model: cfg.ollama_model || 'qwen2.5:14b',
  messages: [
    { role: 'system', content: systemMsg },
    { role: 'user', content: userMsg }
  ],
  stream: false,
  options: { temperature: 0.3, num_predict: 1200 }
};

const url = (cfg.ollama_url || 'http://host.docker.internal:11434').replace(/\/$/, '');

return [{
  json: {
    ...input,
    ollama_url: url,
    ollama_request
  }
}];

const ctx = $('Préparer prompt Ollama').first().json;
const raw = $input.first().json ?? {};
let text = raw?.message?.content || raw?.response || '';
if (typeof text !== 'string') text = JSON.stringify(text);

text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/```json?\n?/gi, '').replace(/```$/g, '').trim();
}

let o = {};
try {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) {
    o = JSON.parse(text.slice(start, end + 1));
  } else {
    throw new Error('Pas de JSON');
  }
} catch (e) {
  o = {
    diagnostic_summary: 'Diagnostic partiel — compléter manuellement (réponse IA non structurée).',
    quick_wins: [],
    roi_estimate: {},
    plan_14_days: [],
    offer_recommendation: { recommended_option: 'A', option_a_price_eur: 2000, option_b_price_eur: 3000 },
    cta_message: 'Proposer un sprint automation de 2 semaines.'
  };
}

return [{ json: { output: o, company_name: ctx.company_name, niche: ctx.niche } }];

const o = $json.output || {};
const companyName = $json.company_name || '';
const niche = $json.niche || '';

const quickWins = Array.isArray(o.quick_wins) ? o.quick_wins : [];
const roi = o.roi_estimate || {};
const offer = o.offer_recommendation || {};

const d = new Date();
const dateStr = d.toISOString().slice(0, 10);
const pageTitle = companyName ? `Diagnostic — ${companyName} — ${dateStr}` : `Diagnostic — ${dateStr}`;

const impactLabel = { high: 'Élevé', medium: 'Moyen', low: 'Faible' };
const effortLabel = { low: 'Faible', medium: 'Moyen', high: 'Élevé' };

const qwLines = quickWins.map((w, i) => {
  const imp = impactLabel[w.impact_level] || w.impact_level || '';
  const ef = effortLabel[w.effort_level] || w.effort_level || '';
  const h = w.expected_hours_saved_weekly || 0;
  const note = (w.implementation_note || '').trim();
  return `${i + 1}. ${w.title || 'Quick win'}\n   Impact: ${imp} · Effort: ${ef} · ~${h} h/sem.\n   ${note}`;
});

const plan = Array.isArray(o.plan_14_days) ? o.plan_14_days : [];
const planLines = plan.map((line) => `- ${line}`).join('\n');
const opt = offer.recommended_option || 'A';

const rapportParts = [
  'Mini-diagnostic automation (démo IA locale)',
  niche ? `Contexte: ${niche}` : null,
  '',
  'Synthèse',
  o.diagnostic_summary || '',
  '',
  '5 quick wins',
  qwLines.join('\n\n') || '(à compléter)',
  '',
  'Estimation ROI',
  `Heures économisées / mois: ${roi.hours_saved_monthly ?? 0}`,
  `Valeur estimée / mois: ${roi.estimated_value_monthly_eur ?? 0} EUR`,
  `Retour indicatif: ~${roi.payback_period_weeks ?? 0} semaine(s)`,
  '',
  'Plan 14 jours',
  planLines,
  '',
  'Recommandation',
  `Option ${opt} — ${offer.reason || ''}`,
  `Sprint essentiel: ${offer.option_a_price_eur ?? 2000} EUR · Sprint complet: ${offer.option_b_price_eur ?? 3000} EUR`,
  '',
  'Prochaine étape',
  o.cta_message || ''
];

const notionRapport = rapportParts.filter((x) => x !== null).join('\n');

return [{
  json: {
    timestamp: d.toISOString(),
    diagnostic_summary: o.diagnostic_summary || '',
    quick_wins_count: quickWins.length,
    quick_wins: quickWins,
    roi_hours_monthly: roi.hours_saved_monthly || 0,
    roi_value_monthly_eur: roi.estimated_value_monthly_eur || 0,
    recommended_option: opt,
    cta_message: o.cta_message || '',
    company_name: companyName,
    page_title: pageTitle,
    notion_rapport: notionRapport,
    ai_provider: 'ollama-local'
  }
}];

const d = $('Formater livrable Notion').first().json;
return [{
  json: {
    success: true,
    company: d.company_name,
    quick_wins: d.quick_wins_count,
    recommended: d.recommended_option,
    summary: d.diagnostic_summary,
    ai: 'ollama-local',
    message: `Diagnostic démo généré pour ${d.company_name} — ${d.quick_wins_count} quick wins`
  }
}];
